insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('bd297c70-0ee6-47e2-8d05-6c790fb50b1a', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', null, 'topic'::public.curated_course_node_type, 'Signal models', 'This module establishes signal models as the course''s first working framework. It supplies the language and representations needed before the path advances to system properties.', 0),
  ('39b53edf-4f10-4adf-b15b-c017ec19fbc8', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'bd297c70-0ee6-47e2-8d05-6c790fb50b1a', 'subtopic'::public.curated_course_node_type, 'Continuous/discrete time', 'Continuous/discrete time identifies a specific object, distinction, or relationship within signal models. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before transformations because that next topic assumes this starting point.', 0),
  ('fea0ee67-5c96-41f3-bbfc-765a78c7b6c1', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'bd297c70-0ee6-47e2-8d05-6c790fb50b1a', 'subtopic'::public.curated_course_node_type, 'Transformations', 'Transformations makes difficult behavior in signal models tractable while exposing the assumptions and accuracy limits used by later methods. After continuous/discrete time, transformations supplies what is needed to address periodicity.', 1),
  ('320c8c14-f791-4e56-8eec-6d6e070e5aa9', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'bd297c70-0ee6-47e2-8d05-6c790fb50b1a', 'subtopic'::public.curated_course_node_type, 'Periodicity', 'Periodicity identifies a specific object, distinction, or relationship within signal models. Learners need to recognize and use it before combining this module''s ideas in later work. After transformations, periodicity supplies what is needed to address energy and power.', 2),
  ('9ef31a7f-3eda-403f-9556-fc8ad5ced81d', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'bd297c70-0ee6-47e2-8d05-6c790fb50b1a', 'subtopic'::public.curated_course_node_type, 'Energy and power', 'Energy and power is a governing quantity in signal models, linking local calculations to system-level behavior and offering a consistency check. As the final topic in this module, energy and power carries the completed idea into system properties.', 3),
  ('4b930aea-5034-41a9-b4d7-4e170154488f', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', null, 'topic'::public.curated_course_node_type, 'System properties', 'This module builds directly on signal models and develops system properties. It belongs here because its methods and distinctions are prerequisites for lti systems.', 1),
  ('0da19835-1965-43dc-a7b2-a72978580ff6', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '4b930aea-5034-41a9-b4d7-4e170154488f', 'subtopic'::public.curated_course_node_type, 'Linearity', 'Linearity identifies a specific object, distinction, or relationship within system properties. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before time invariance because that next topic assumes this starting point.', 0),
  ('eb5a5c79-99b1-48b8-8c49-55da27887c6a', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '4b930aea-5034-41a9-b4d7-4e170154488f', 'subtopic'::public.curated_course_node_type, 'Time invariance', 'Time invariance identifies a specific object, distinction, or relationship within system properties. Learners need to recognize and use it before combining this module''s ideas in later work. After linearity, time invariance supplies what is needed to address causality.', 1),
  ('19ea33a3-05ef-452f-9d95-c5f5effcf067', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '4b930aea-5034-41a9-b4d7-4e170154488f', 'subtopic'::public.curated_course_node_type, 'Causality', 'Causality identifies a specific object, distinction, or relationship within system properties. Learners need to recognize and use it before combining this module''s ideas in later work. After time invariance, causality supplies what is needed to address memory.', 2),
  ('581b1fa7-585e-494a-ae32-58bf4cd425ec', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '4b930aea-5034-41a9-b4d7-4e170154488f', 'subtopic'::public.curated_course_node_type, 'Memory', 'Memory identifies a specific object, distinction, or relationship within system properties. Learners need to recognize and use it before combining this module''s ideas in later work. After causality, memory supplies what is needed to address stability.', 3),
  ('bb34f842-44ee-452a-8a01-badaf469ec45', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '4b930aea-5034-41a9-b4d7-4e170154488f', 'subtopic'::public.curated_course_node_type, 'Stability', 'Stability makes the validity limits of system properties explicit, showing when an otherwise correct method or system can become unreliable. As the final topic in this module, stability carries the completed idea into lti systems.', 4),
  ('b4468c16-8fbe-4beb-8900-618b899c248c', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', null, 'topic'::public.curated_course_node_type, 'LTI systems', 'This module builds directly on system properties and develops lti systems. It belongs here because its methods and distinctions are prerequisites for differential-equation models.', 2),
  ('6294d0b5-0931-4801-a5ff-0c2d73e75968', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'b4468c16-8fbe-4beb-8900-618b899c248c', 'subtopic'::public.curated_course_node_type, 'Impulse response', 'Impulse response identifies a specific object, distinction, or relationship within lti systems. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before convolution because that next topic assumes this starting point.', 0),
  ('be87497b-ecca-40be-aebc-65d4e32ecb0e', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'b4468c16-8fbe-4beb-8900-618b899c248c', 'subtopic'::public.curated_course_node_type, 'Convolution', 'Convolution identifies a specific object, distinction, or relationship within lti systems. Learners need to recognize and use it before combining this module''s ideas in later work. After impulse response, convolution supplies what is needed to address interconnections.', 1),
  ('56175bff-7cae-4600-bdde-78a48a2f6062', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'b4468c16-8fbe-4beb-8900-618b899c248c', 'subtopic'::public.curated_course_node_type, 'Interconnections', 'Interconnections identifies a specific object, distinction, or relationship within lti systems. Learners need to recognize and use it before combining this module''s ideas in later work. After convolution, interconnections supplies what is needed to address difference equations.', 2),
  ('b9ecd965-795e-43bc-9b7e-488151a42162', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'b4468c16-8fbe-4beb-8900-618b899c248c', 'subtopic'::public.curated_course_node_type, 'Difference equations', 'Difference equations identifies a specific object, distinction, or relationship within lti systems. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, difference equations carries the completed idea into differential-equation models.', 3),
  ('90bfecf5-d420-4b3b-a580-190808164a10', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', null, 'topic'::public.curated_course_node_type, 'Differential-equation models', 'This module builds directly on lti systems and develops differential-equation models. It belongs here because its methods and distinctions are prerequisites for fourier series.', 3),
  ('f94de476-d7df-4f33-bcbb-342f4a747d50', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '90bfecf5-d420-4b3b-a580-190808164a10', 'subtopic'::public.curated_course_node_type, 'Natural and forced response', 'Natural and forced response is a governing quantity in differential-equation models, linking local calculations to system-level behavior and offering a consistency check. It appears before eigenfunctions because that next topic assumes this starting point.', 0),
  ('10bfc249-fcf5-47f2-ad79-d14b3e3400a5', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '90bfecf5-d420-4b3b-a580-190808164a10', 'subtopic'::public.curated_course_node_type, 'Eigenfunctions', 'Eigenfunctions identifies a specific object, distinction, or relationship within differential-equation models. Learners need to recognize and use it before combining this module''s ideas in later work. After natural and forced response, eigenfunctions supplies what is needed to address resonance.', 1),
  ('7546e094-4eb1-4c86-b6cd-91eb1655c9e0', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '90bfecf5-d420-4b3b-a580-190808164a10', 'subtopic'::public.curated_course_node_type, 'Resonance', 'Resonance identifies a specific object, distinction, or relationship within differential-equation models. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, resonance carries the completed idea into fourier series.', 2),
  ('b2e4f882-6272-4454-a45f-6faed09a0a34', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', null, 'topic'::public.curated_course_node_type, 'Fourier series', 'This module builds directly on differential-equation models and develops fourier series. It belongs here because its methods and distinctions are prerequisites for continuous-time fourier transform.', 4),
  ('fb92b78c-307f-4190-9ecc-31267c305a46', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'b2e4f882-6272-4454-a45f-6faed09a0a34', 'subtopic'::public.curated_course_node_type, 'Complex exponentials', 'Complex exponentials identifies a specific object, distinction, or relationship within fourier series. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before convergence because that next topic assumes this starting point.', 0),
  ('f4b7d86c-9adc-4abf-9184-19e3a3a7828c', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'b2e4f882-6272-4454-a45f-6faed09a0a34', 'subtopic'::public.curated_course_node_type, 'Convergence', 'Convergence makes difficult behavior in fourier series tractable while exposing the assumptions and accuracy limits used by later methods. After complex exponentials, convergence supplies what is needed to address symmetry.', 1),
  ('6e2ebf9f-3672-4ad3-8b24-aa7c2451413b', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'b2e4f882-6272-4454-a45f-6faed09a0a34', 'subtopic'::public.curated_course_node_type, 'Symmetry', 'Symmetry identifies a specific object, distinction, or relationship within fourier series. Learners need to recognize and use it before combining this module''s ideas in later work. After convergence, symmetry supplies what is needed to address line spectra.', 2),
  ('5cad8db5-4443-4ad5-91f3-68805920ee60', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'b2e4f882-6272-4454-a45f-6faed09a0a34', 'subtopic'::public.curated_course_node_type, 'Line spectra', 'Line spectra identifies a specific object, distinction, or relationship within fourier series. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, line spectra carries the completed idea into continuous-time fourier transform.', 3),
  ('879ed2d6-3797-4b2e-a290-2f4531a27c50', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', null, 'topic'::public.curated_course_node_type, 'Continuous-time Fourier transform', 'This module builds directly on fourier series and develops continuous-time fourier transform. It belongs here because its methods and distinctions are prerequisites for discrete-time fourier transform.', 5),
  ('a8181fe8-dfed-42e1-8831-a1ba4c98b20e', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '879ed2d6-3797-4b2e-a290-2f4531a27c50', 'subtopic'::public.curated_course_node_type, 'Properties', 'Properties identifies a specific object, distinction, or relationship within continuous-time fourier transform. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before modulation because that next topic assumes this starting point.', 0),
  ('a8fd1393-328e-4771-a7c5-452362b7b650', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '879ed2d6-3797-4b2e-a290-2f4531a27c50', 'subtopic'::public.curated_course_node_type, 'Modulation', 'Modulation identifies a specific object, distinction, or relationship within continuous-time fourier transform. Learners need to recognize and use it before combining this module''s ideas in later work. After properties, modulation supplies what is needed to address filtering.', 1),
  ('175bb624-40e1-40d1-b8db-d8539a1629f0', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '879ed2d6-3797-4b2e-a290-2f4531a27c50', 'subtopic'::public.curated_course_node_type, 'Filtering', 'Filtering identifies a specific object, distinction, or relationship within continuous-time fourier transform. Learners need to recognize and use it before combining this module''s ideas in later work. After modulation, filtering supplies what is needed to address bandwidth.', 2),
  ('d6e2c17b-81f5-4aab-9e1b-38b2a365f748', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '879ed2d6-3797-4b2e-a290-2f4531a27c50', 'subtopic'::public.curated_course_node_type, 'Bandwidth', 'Bandwidth identifies a specific object, distinction, or relationship within continuous-time fourier transform. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, bandwidth carries the completed idea into discrete-time fourier transform.', 3),
  ('b0cd0d9a-5589-49c3-839c-92500023d88c', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', null, 'topic'::public.curated_course_node_type, 'Discrete-time Fourier transform', 'This module builds directly on continuous-time fourier transform and develops discrete-time fourier transform. It belongs here because its methods and distinctions are prerequisites for sampling and reconstruction.', 6),
  ('b105cbea-5ebd-44ad-bbfb-853ec61569e4', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'b0cd0d9a-5589-49c3-839c-92500023d88c', 'subtopic'::public.curated_course_node_type, 'Periodic spectra', 'Periodic spectra identifies a specific object, distinction, or relationship within discrete-time fourier transform. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before frequency response because that next topic assumes this starting point.', 0),
  ('b0aaff33-c4eb-4b53-a9f0-7a5a171466a0', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'b0cd0d9a-5589-49c3-839c-92500023d88c', 'subtopic'::public.curated_course_node_type, 'Frequency response', 'Frequency response identifies a specific object, distinction, or relationship within discrete-time fourier transform. Learners need to recognize and use it before combining this module''s ideas in later work. After periodic spectra, frequency response supplies what is needed to address computation.', 1),
  ('06585ee0-8647-41ca-9857-2cbd083c7056', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', 'b0cd0d9a-5589-49c3-839c-92500023d88c', 'subtopic'::public.curated_course_node_type, 'Computation', 'Computation is an executable part of discrete-time fourier transform; its correctness, cost, and failure modes recur in later problems and implementations. As the final topic in this module, computation carries the completed idea into sampling and reconstruction.', 2),
  ('1f3ee61a-c2a8-4906-9d0f-24da5b81be4e', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', null, 'topic'::public.curated_course_node_type, 'Sampling and reconstruction', 'This module builds directly on discrete-time fourier transform and develops sampling and reconstruction. It belongs here because its methods and distinctions are prerequisites for laplace transform.', 7),
  ('ec84fd98-4d58-436f-85a5-33ad991fdafa', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '1f3ee61a-c2a8-4906-9d0f-24da5b81be4e', 'subtopic'::public.curated_course_node_type, 'Impulse sampling', 'Impulse sampling identifies a specific object, distinction, or relationship within sampling and reconstruction. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before aliasing because that next topic assumes this starting point.', 0),
  ('b1aaf602-f03f-4fca-937d-7d25cf55d87e', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '1f3ee61a-c2a8-4906-9d0f-24da5b81be4e', 'subtopic'::public.curated_course_node_type, 'Aliasing', 'Aliasing identifies a specific object, distinction, or relationship within sampling and reconstruction. Learners need to recognize and use it before combining this module''s ideas in later work. After impulse sampling, aliasing supplies what is needed to address anti-alias and interpolation filters.', 1),
  ('1cf61f22-48dc-4ae1-8187-c9d8c510140b', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '1f3ee61a-c2a8-4906-9d0f-24da5b81be4e', 'subtopic'::public.curated_course_node_type, 'Anti-alias and interpolation filters', 'Anti-alias and interpolation filters identifies a specific object, distinction, or relationship within sampling and reconstruction. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, anti-alias and interpolation filters carries the completed idea into laplace transform.', 2),
  ('3fe02406-9761-464e-a173-bb6ecce32faa', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', null, 'topic'::public.curated_course_node_type, 'Laplace transform', 'This module builds directly on sampling and reconstruction and develops laplace transform. It belongs here because its methods and distinctions are prerequisites for z-transform.', 8),
  ('8d34b220-ab0b-4e27-914a-edc6bf1900c5', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '3fe02406-9761-464e-a173-bb6ecce32faa', 'subtopic'::public.curated_course_node_type, 'ROC', 'ROC identifies a specific object, distinction, or relationship within laplace transform. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before poles/zeros because that next topic assumes this starting point.', 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('dd33364c-627d-4dc8-8272-bb9ba57cae7f', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '3fe02406-9761-464e-a173-bb6ecce32faa', 'subtopic'::public.curated_course_node_type, 'Poles/zeros', 'Poles/zeros identifies a specific object, distinction, or relationship within laplace transform. Learners need to recognize and use it before combining this module''s ideas in later work. After roc, poles/zeros supplies what is needed to address stability.', 1),
  ('352bb81a-095b-4168-9d4f-27c2394344a3', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '3fe02406-9761-464e-a173-bb6ecce32faa', 'subtopic'::public.curated_course_node_type, 'Stability', 'Stability makes the validity limits of laplace transform explicit, showing when an otherwise correct method or system can become unreliable. After poles/zeros, stability supplies what is needed to address inverse transforms.', 2),
  ('4614a391-f58f-4c19-bed5-1ee0b063917b', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '3fe02406-9761-464e-a173-bb6ecce32faa', 'subtopic'::public.curated_course_node_type, 'Inverse transforms', 'Inverse transforms makes difficult behavior in laplace transform tractable while exposing the assumptions and accuracy limits used by later methods. After stability, inverse transforms supplies what is needed to address unilateral form.', 3),
  ('54e19a97-3623-4596-84ff-4c56366a5d3f', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '3fe02406-9761-464e-a173-bb6ecce32faa', 'subtopic'::public.curated_course_node_type, 'Unilateral form', 'Unilateral form identifies a specific object, distinction, or relationship within laplace transform. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, unilateral form carries the completed idea into z-transform.', 4),
  ('78abb135-a13a-4bda-9aaf-ef19632fbef2', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', null, 'topic'::public.curated_course_node_type, 'z-transform', 'This module builds directly on laplace transform and develops z-transform. It belongs here because its methods and distinctions are prerequisites for frequency-selective systems.', 9),
  ('df8d468d-b372-45a0-8780-c11102e51f12', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '78abb135-a13a-4bda-9aaf-ef19632fbef2', 'subtopic'::public.curated_course_node_type, 'ROC', 'ROC identifies a specific object, distinction, or relationship within z-transform. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before rational systems because that next topic assumes this starting point.', 0),
  ('15a24ecc-0683-4046-bbb1-6005526dd858', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '78abb135-a13a-4bda-9aaf-ef19632fbef2', 'subtopic'::public.curated_course_node_type, 'Rational systems', 'Rational systems gives z-transform a reusable representation for organizing assumptions, variables, and relationships before analysis begins. After roc, rational systems supplies what is needed to address causal/stable realizations.', 1),
  ('89e88aef-f311-4e37-a3db-e5a95ffc3a16', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '78abb135-a13a-4bda-9aaf-ef19632fbef2', 'subtopic'::public.curated_course_node_type, 'Causal/stable realizations', 'Causal/stable realizations identifies a specific object, distinction, or relationship within z-transform. Learners need to recognize and use it before combining this module''s ideas in later work. After rational systems, causal/stable realizations supplies what is needed to address inverse methods.', 2),
  ('dd5b830a-3ec2-4cb3-8953-c88eba2506d4', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '78abb135-a13a-4bda-9aaf-ef19632fbef2', 'subtopic'::public.curated_course_node_type, 'Inverse methods', 'Inverse methods identifies a specific object, distinction, or relationship within z-transform. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, inverse methods carries the completed idea into frequency-selective systems.', 3),
  ('283a09a4-d879-4593-b77c-030901683098', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', null, 'topic'::public.curated_course_node_type, 'Frequency-selective systems', 'This module builds directly on z-transform and develops frequency-selective systems. It belongs here because its methods and distinctions are prerequisites for state and application synthesis.', 10),
  ('21eeb8a1-56a2-4f3a-998a-9f5c0f80fe68', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '283a09a4-d879-4593-b77c-030901683098', 'subtopic'::public.curated_course_node_type, 'Bode ideas', 'Bode ideas identifies a specific object, distinction, or relationship within frequency-selective systems. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before filter specifications because that next topic assumes this starting point.', 0),
  ('706b4f9f-4041-4458-ae91-8bc54439ab04', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '283a09a4-d879-4593-b77c-030901683098', 'subtopic'::public.curated_course_node_type, 'Filter specifications', 'Filter specifications identifies a specific object, distinction, or relationship within frequency-selective systems. Learners need to recognize and use it before combining this module''s ideas in later work. After bode ideas, filter specifications supplies what is needed to address distortion.', 1),
  ('6846bfcd-266f-4a91-9a98-83eb733ca24b', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '283a09a4-d879-4593-b77c-030901683098', 'subtopic'::public.curated_course_node_type, 'Distortion', 'Distortion identifies a specific object, distinction, or relationship within frequency-selective systems. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, distortion carries the completed idea into state and application synthesis.', 2),
  ('0b7e6652-fe67-44ac-977a-7d3229e81f35', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', null, 'topic'::public.curated_course_node_type, 'State and application synthesis', 'This culminating module draws on frequency-selective systems and develops state and application synthesis. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('9b07befa-a1b5-429c-9a14-5fb04f3a025a', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '0b7e6652-fe67-44ac-977a-7d3229e81f35', 'subtopic'::public.curated_course_node_type, 'State-space concepts', 'State-space concepts gives state and application synthesis a reusable representation for organizing assumptions, variables, and relationships before analysis begins. It appears before feedback because that next topic assumes this starting point.', 0),
  ('0cedcc02-1436-4368-a2ce-9247fba1547a', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '0b7e6652-fe67-44ac-977a-7d3229e81f35', 'subtopic'::public.curated_course_node_type, 'Feedback', 'Feedback identifies a specific object, distinction, or relationship within state and application synthesis. Learners need to recognize and use it before combining this module''s ideas in later work. After state-space concepts, feedback supplies what is needed to address end-to-end signal chain.', 1),
  ('4c3cc120-8d5f-419c-b2ec-e12509b91871', 'b98db445-4cc4-4ecb-b887-080d9dbd1a87', '0b7e6652-fe67-44ac-977a-7d3229e81f35', 'subtopic'::public.curated_course_node_type, 'End-to-end signal chain', 'End-to-end signal chain identifies a specific object, distinction, or relationship within state and application synthesis. Learners need to recognize and use it before combining this module''s ideas in later work. As the final course topic, end-to-end signal chain requires ideas from the complete path to be integrated and transferred.', 2);
